/* Pure helpers shared by the browser app and the server: dates, money, categories, sorting. */

export const WD = "日月火水木金土";
export const pad = n => String(n).padStart(2, "0");
export const parseD = s => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || ""); return m ? new Date(+m[1], +m[2] - 1, +m[3]) : null; };
export const iso = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
export const todayISO = () => iso(new Date());
export const addDays = (s, n) => { const d = parseD(s); if (!d) return ""; d.setDate(d.getDate() + n); return iso(d); };
export const diffDays = (a, b) => { const x = parseD(a), y = parseD(b); return x && y ? Math.round((y - x) / 864e5) : 0; };
export const mdw = s => { const d = parseD(s); return d ? `${d.getMonth() + 1}/${d.getDate()}(${WD[d.getDay()]})` : ""; };
export const mdj = s => { const d = parseD(s); return d ? `${d.getMonth() + 1}月${d.getDate()}日` : ""; };
export const tmin = s => { const m = /^(\d{1,2}):(\d{2})/.exec(s || ""); return m ? +m[1] * 60 + +m[2] : null; };
export const dur = n => { const h = Math.floor(n / 60), m = n % 60; return h ? (m ? `${h}時間${m}分` : `${h}時間`) : `${m}分`; };
export const yen = n => "¥" + Math.round(n || 0).toLocaleString("ja-JP");
export const toNum = v => {
  const s = String(v == null ? "" : v).replace(/[０-９]/g, c => String.fromCharCode(c.charCodeAt(0) - 65248)).replace(/[,，円¥￥\s]/g, "");
  if (!s) return null;
  const n = Number(s);
  return Number.isFinite(n) && n >= 0 ? Math.round(n) : null;
};
export const clip = (s, n) => String(s == null ? "" : s).trim().slice(0, n);
export const byCreated = (x, y) => (x.createdAt || 0) - (y.createdAt || 0);

export function tripDays(t) {
  if (!t || !parseD(t.start)) return [];
  const n = Math.max(0, Math.min(parseD(t.end) ? diffDays(t.start, t.end) : 0, 30));
  return Array.from({ length: n + 1 }, (_, i) => addDays(t.start, i));
}
export const nightsDays = t => { const n = tripDays(t).length; return n <= 1 ? "日帰り" : `${n - 1}泊${n}日`; };
export const monthOf = t => { const d = parseD(t && t.start) || new Date(); return d.getMonth() + 1; };

/* categories: single-kanji marks, like the boxed marks on a ticket */
export const CATS = [
  { key: "see", kanji: "観", label: "見る" },
  { key: "eat", kanji: "食", label: "食べる" },
  { key: "play", kanji: "遊", label: "遊ぶ・体験" },
  { key: "shop", kanji: "買", label: "買う" },
  { key: "stay", kanji: "宿", label: "泊まる" },
  { key: "move", kanji: "移", label: "移動" },
  { key: "other", kanji: "他", label: "その他" },
];
export const SPOT_CATS = CATS.filter(c => c.key !== "move");
export const MONEY_CATS = [
  { key: "move", kanji: "移", label: "交通" },
  { key: "stay", kanji: "宿", label: "宿" },
  { key: "eat", kanji: "食", label: "食事" },
  { key: "see", kanji: "観", label: "観光・体験" },
  { key: "shop", kanji: "買", label: "おみやげ・買い物" },
  { key: "other", kanji: "他", label: "その他" },
];
export const cat = k => CATS.find(c => c.key === k) || CATS[CATS.length - 1];
export const mcat = k => MONEY_CATS.find(c => c.key === k) || MONEY_CATS[MONEY_CATS.length - 1];
export const PACK_GROUPS = ["衣類", "洗面・美容", "電子機器", "貴重品・書類", "その他"];

export const isBoth = s => !!(s.likes && s.likes.a && s.likes.b);
export function sortPlan(arr) {
  return arr.slice().sort((a, b) => (a.date || "9999").localeCompare(b.date || "9999") ||
    ((tmin(a.time) == null ? 1e4 : tmin(a.time)) - (tmin(b.time) == null ? 1e4 : tmin(b.time))) || byCreated(a, b));
}

/* Document paths the app stores (the database's doc_write() accepts only these):
   app/members, trips/{id}, trips/{id}/(plan|money|checks)/{id}, spots/{id}, memories/{id} */
export const DOC_ID = "[A-Za-z0-9_-]{1,40}";
export const TRIP_PARTS = ["plan", "money", "checks"];
export const validId = id => typeof id === "string" && new RegExp(`^${DOC_ID}$`).test(id);

/* the wish list is shared by the two; a spot may be tagged as a candidate for one trip */
export const spotsOfTrip = (spots, trip) => (trip ? spots.filter(s => s.tripId === trip.id) : []);
